type Call = string | [string, string];

function mount(source: string, destination: string, rw = true, mode = ""): { Type: string; Source: string; Destination: string; RW: boolean; Mode: string } {
	return { Type: "bind", Source: source, Destination: destination, RW: rw, Mode: mode };
}

function makeSandbox(resolvePackLocalDataMounts?: () => readonly PackLocalDataMountPlan[]): ProjectSandbox {
	return new ProjectSandbox({
		projectId: "stale-agent-dir-mounts",
		projectDir: path.join(process.cwd(), "tmp-project"),
		repoUrl: "https://example.test/repo.git",
		image: "bobbit-test-image:latest",
		resolvePackLocalDataMounts,
	});
}

function requiredStateMounts(stateDir: string) {
	return [
		mount(path.join(stateDir, "sessions"), "/bobbit-state/sessions"),
		mount(path.join(stateDir, "tool-guard"), "/bobbit-state/tool-guard"),
		mount(path.join(stateDir, "html-snapshots"), "/bobbit-state/html-snapshots"),
		mount(path.join(stateDir, "google-code-assist"), "/bobbit-state/google-code-assist", false, "ro"),
		mount(path.join(stateDir, "tool-result-error-bridge"), "/bobbit-state/tool-result-error-bridge", false, "ro"),
		mount(path.join(stateDir, "aigw-dns-guard"), "/bobbit-state/aigw-dns-guard", false, "ro"),
		mount(path.join(bobbitStateDir(), "tool-extension-activation"), "/bobbit-state/tool-extension-activation", false, "ro"),
	];
}

